[https://github.com/jaliyaudagedara/repro-aspnetcore-openapi-dup-schemas](https://github.com/jaliyaudagedara/repro-aspnetcore-openapi-dup-schemas)

Updated the original issue with the link as well.

Issue seems to be here:
https://github.com/dotnet/aspnetcore/blob/af22effae4069a5dfb9b0735859de48820104f5b/src/OpenApi/src/Services/Schemas/OpenApiSchemaStore.cs#L154

```json
{
    "type": "array",
    "items": {
        "type": "object",
        "properties": {
            "location": {
                "type": "object",
                "properties": {
                    "address": {
                        "type": "object",
                        "properties": {
                            "relatedLocation": {
                                "type": "object",
                                "properties": {
                                    "address": {
                                        "$ref": "#/items/properties/location/properties/address",
                                        "x-schema-id": "AddressDto"
                                    }
                                },
                                "x-schema-id": "LocationDto"
                            }
                        },
                        "x-schema-id": "AddressDto"
                    }
                },
                "x-schema-id": "LocationDto"
            }
        },
        "x-schema-id": "WeatherForecast"
    }
}
```
`LocationDto` schema is different.

```json
{
    "type": "object",
    "properties": {
        "address": {
            "$ref": "#/items/properties/location/properties/address",
            "x-schema-id": "AddressDto"
        }
    },
    "x-schema-id": "LocationDto"
}

{
    "type": "object",
    "properties": {
        "address": {
            "type": "object",
            "properties": {
                "relatedLocation": {
                    "type": "object",
                    "properties": {
                        "address": {
                            "$ref": "#/items/properties/location/properties/address",
                            "x-schema-id": "AddressDto"
                        }
                    },
                    "x-schema-id": "LocationDto"
                }
            },
            "x-schema-id": "AddressDto"
        }
    },
    "x-schema-id": "LocationDto"
}
```

Should the OpenApiSchema for `WeatherForecast` be this,
```json
{
    "type": "object",
    "properties": {
        "location": {
            "type": "object",
            "properties": {
                "address": {
                    "type": "object",
                    "properties": {
                        "relatedLocation": {
                            "type": "object",
                            "properties": {
                                "address": {
                                    "$ref": "#/items/properties/location/properties/address",
                                    "x-schema-id": "AddressDto"
                                }
                            },
                            // added
                            "$ref": "#/items/properties/location",
                            "x-schema-id": "LocationDto"
                        }
                    },
                    "x-schema-id": "AddressDto"
                }
            },
            "x-schema-id": "LocationDto"
        }
    },
    "x-schema-id": "WeatherForecast"
}
```

Updated the repro with minimal APIs,
```csharp
WebApplicationBuilder builder = WebApplication.CreateBuilder(args);

// Learn more about configuring OpenAPI at https://aka.ms/aspnet/openapi
builder.Services.AddOpenApi();

WebApplication app = builder.Build();

app.MapOpenApi();
app.UseSwaggerUI(x =>
{
    x.SwaggerEndpoint("/openapi/v1.json", "My API");
});

app.UseHttpsRedirection();

app.MapGet("/weatherforecast", () =>
{
    return Enumerable.Empty<WeatherForecast>();
})
.Produces<IEnumerable<WeatherForecast>>()
.WithName("GetWeatherForecasts");

app.MapPost("/weatherforecast", (WeatherForecast weatherForecast) =>
{
    return weatherForecast;
})
.Produces<WeatherForecast>()
.WithName("CreateWeatherForecast");

app.Run();

public class WeatherForecast
{
    public LocationDto Location { get; set; }
}

public class LocationDto
{
    public AddressDto Address { get; set; }
}

public class AddressDto
{
    public LocationDto RelatedLocation { get; set; }
}
